import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Globe, ArrowRight, Loader2 } from 'lucide-react';

const HrRegistration = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);

  const handleRegister = (e) => {
    e.preventDefault();
    setIsLoading(true);
    // Logic to send to backend /api/register/hr
    setTimeout(() => {
      setIsLoading(false);
      navigate('/admin'); // Redirect to dashboard after success
    }, 2000);
  };

  return (
    <div className="min-h-screen flex font-sans bg-white">
      {/* LEFT SIDE: Hero / Branding */}
      <div className="hidden lg:flex lg:w-1/2 relative flex-col justify-end p-20 overflow-hidden">
        {/* Blue Overlay matching your screenshot */}
        <div className="absolute inset-0 bg-blue-700/85 mix-blend-multiply z-10"></div>
        <img 
          src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&q=80&w=2070" 
          className="absolute inset-0 w-full h-full object-cover" 
          alt="HR Professionals" 
        />
        
        <div className="relative z-20">
          <div className="flex items-center gap-2 text-white font-bold text-2xl mb-12 absolute top-[-150%]">
             <Globe size={32} className="text-white" /> TalentPool
          </div>
          <h2 className="text-5xl font-extrabold text-white leading-[1.1] mb-8 max-w-lg">
            "Discover, manage, and hire top-tier talent faster than ever before."
          </h2>
          <p className="text-white/90 text-lg font-medium">
            Join thousands of HR professionals building better teams.
          </p>
        </div>
      </div>

      {/* RIGHT SIDE: Registration Form */}
      <div className="w-full lg:w-1/2 flex flex-col justify-center px-8 lg:px-24 py-16 overflow-y-auto">
        <div className="max-w-md w-full mx-auto">
          <header className="mb-12">
            <h1 className="text-3xl font-bold text-slate-900 mb-3 tracking-tight">Create Employer Account</h1>
            <p className="text-slate-500 text-sm leading-relaxed">
              Register your company to start posting jobs and finding candidates for your open requirements.
            </p>
          </header>

          <form onSubmit={handleRegister} className="space-y-6">
            {/* Personal Info Section */}
            <div className="space-y-5">
              <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">
                Personal Information
              </h3>
              
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700 ml-1">Full Name</label>
                <input type="text" placeholder="e.g. Sarah Jenkins" className="hr-input-style" required />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700 ml-1">Work Email Address</label>
                <input type="email" placeholder="sarah@company.com" className="hr-input-style" required />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-700 ml-1">Password</label>
                  <input type="password" placeholder="••••••••" className="hr-input-style" required />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-700 ml-1">Confirm Password</label>
                  <input type="password" placeholder="••••••••" className="hr-input-style" required />
                </div>
              </div>
            </div>

            {/* Company Info Section */}
            <div className="space-y-5 pt-4">
              <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-2">
                Company Details
              </h3>
              
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700 ml-1">Company Name</label>
                <input type="text" placeholder="e.g. TechCorp Inc." className="hr-input-style" required />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700 ml-1">Company Website</label>
                <input type="url" placeholder="https://www.example.com" className="hr-input-style" required />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-700 ml-1">Industry</label>
                  <select className="hr-input-style bg-slate-50 cursor-pointer">
                    <option>Select Industry</option>
                    <option>Technology</option>
                    <option>Finance</option>
                    <option>Healthcare</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-700 ml-1">Company Size</label>
                  <select className="hr-input-style bg-slate-50 cursor-pointer">
                    <option>Select Size</option>
                    <option>1-50</option>
                    <option>51-200</option>
                    <option>201-1000</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Submit Button */}
            <button 
              type="submit" 
              disabled={isLoading}
              className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all transform active:scale-[0.98] mt-6 flex items-center justify-center gap-2"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : (
                <>Register as HR <ArrowRight size={18} /></>
              )}
            </button>
            
            <p className="text-center text-sm text-slate-500 pt-4">
              Already have an account? <span onClick={() => navigate('/')} className="text-blue-600 font-bold hover:underline cursor-pointer">Sign in</span>
            </p>
          </form>
        </div>
      </div>

      {/* Internal CSS for the professional inputs */}
      <style>{`
        .hr-input-style {
          width: 100%;
          padding: 0.85rem 1.25rem;
          border: 1px solid #f1f5f9;
          background-color: #f8fafc;
          border-radius: 0.75rem;
          font-size: 0.875rem;
          color: #1e293b;
          outline: none;
          transition: all 0.2s;
        }
        .hr-input-style:focus {
          border-color: #2563eb;
          background-color: #ffffff;
          box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.1);
        }
        .hr-input-style::placeholder {
          color: #94a3b8;
        }
      `}</style>
    </div>
  );
};

export default HrRegistration;
